 import React, { Component } from "react";
import Slider from "react-slick";




export default function SimpleSlider() {
  var settings = {
    // dots: true,
    // infinite: true,
     speed: 500,
    // slidesToShow: 1,
    // slidesToScroll: 3
  };
  return (
    <div className="slider">
<Slider {...settings}>
      <div>
        <h3>
<img src={sec1} alt="" />
        </h3>
      </div>
      <div>
        <h3>
        <img src={sec1} alt="" />
        </h3>
      </div>
